function(x=stats::runif(10),y=stats::runif(10),pch=1,size=unit(1,'char'),default.units='native',name=NULL,gp=gpar(),vp=NULL) { if (!is.unit(x)) x<-unit(x,default.units); if (!is.unit(y)) y<-unit(y,default.units); if (!is.unit(size)) stop("'x', 'y' and 'size' must be units"); if (length(x) != length(y)) stop("'x' and 'y' must have the same length"); structure(list(primitive='points',data=list(x=x,y=y,pch=pch,size=size,default.units=default.units),name=name,gp=gp,vp=vp),class=c('points','grob','gDesc')) }
